('psy-rnk-l1-01', 'RNK-L1-01', 'psychology', 'ranking-ordering', 1, 'ஒரு அணிவகுப்பு வரிசையில் காவலர் முருகன் இடமிருந்து 13-வது இடத்திலும், வலமிருந்து 18-வது இடத்திலும் உள்ளார் எனில், வரிசையில் உள்ள மொத்த நபர்கள் எத்தனை பேர்? (அடிப்படை வரிசை #1)', '["30","31","29","32"]'::jsonb, 0, 'மொத்த நபர்கள் = (இடது + வலது) − 1 = (13 + 18) − 1 = 30 பேர்.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', '24a0cc50d7d9c428e82acb21e8fb68f0be0329f3576ee99f4ba7ea84a8fe9a60'),
('psy-rnk-l1-02', 'RNK-L1-02', 'psychology', 'ranking-ordering', 1, 'ஒரு அணிவகுப்பு வரிசையில் SI கார்த்திக் இடமிருந்து 15-வது இடத்திலும், வலமிருந்து 19-வது இடத்திலும் உள்ளார் எனில், வரிசையில் உள்ள மொத்த நபர்கள் எத்தனை பேர்? (அடிப்படை வரிசை #2)', '["33","34","32","35"]'::jsonb, 0, 'மொத்த நபர்கள் = (இடது + வலது) − 1 = (15 + 19) − 1 = 33 பேர்.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', '4b050d4f50e77aa168b7a4feaaa2217eabb01e4e7b3cc12b18a85f98a20b0b62'),
('psy-rnk-l1-03', 'RNK-L1-03', 'psychology', 'ranking-ordering', 1, 'ஒரு அணிவகுப்பு வரிசையில் ஆய்வாளர் ரமேஷ் இடமிருந்து 17-வது இடத்திலும், வலமிருந்து 20-வது இடத்திலும் உள்ளார் எனில், வரிசையில் உள்ள மொத்த நபர்கள் எத்தனை பேர்? (அடிப்படை வரிசை #3)', '["36","37","35","38"]'::jsonb, 0, 'மொத்த நபர்கள் = (இடது + வலது) − 1 = (17 + 20) − 1 = 36 பேர்.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', 'ac9e9a4f8f33fe99421747dc972f96e4f17187bb2fdf1c7fb1363b8840c633c0'),
('psy-rnk-l1-04', 'RNK-L1-04', 'psychology', 'ranking-ordering', 1, 'ஒரு அணிவகுப்பு வரிசையில் காவலர் செந்தில் இடமிருந்து 19-வது இடத்திலும், வலமிருந்து 21-வது இடத்திலும் உள்ளார் எனில், வரிசையில் உள்ள மொத்த நபர்கள் எத்தனை பேர்? (அடிப்படை வரிசை #4)', '["39","40","38","41"]'::jsonb, 0, 'மொத்த நபர்கள் = (இடது + வலது) − 1 = (19 + 21) − 1 = 39 பேர்.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', 'd98b7d64f27d27e15b063536a28bcef79d21a3ef4dfb6db015e50c42ddeac7a8'),
