('psy-rnk-l1-25', 'RNK-L1-25', 'psychology', 'ranking-ordering', 1, 'ஒரு அணிவகுப்பு வரிசையில் காவலர் தீபன் இடமிருந்து 61-வது இடத்திலும், வலமிருந்து 42-வது இடத்திலும் உள்ளார் எனில், வரிசையில் உள்ள மொத்த நபர்கள் எத்தனை பேர்? (அடிப்படை வரிசை #25)', '["102","103","101","104"]'::jsonb, 0, 'மொத்த நபர்கள் = (இடது + வலது) − 1 = (61 + 42) − 1 = 102 பேர்.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', 'bd6d06c4db9fba24fd028e950019e3bd707d9867eaf5dd0792c708bdd7256334'),
('psy-rnk-l1-26', 'RNK-L1-26', 'psychology', 'ranking-ordering', 1, 'ஒரு அணிவகுப்பு வரிசையில் SI மோகன் இடமிருந்து 63-வது இடத்திலும், வலமிருந்து 43-வது இடத்திலும் உள்ளார் எனில், வரிசையில் உள்ள மொத்த நபர்கள் எத்தனை பேர்? (அடிப்படை வரிசை #26)', '["105","106","104","107"]'::jsonb, 0, 'மொத்த நபர்கள் = (இடது + வலது) − 1 = (63 + 43) − 1 = 105 பேர்.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', 'f732a3b9ec288ac1d75129bf7059f279b508c5c90b6b3f234113ef0b0d307d26'),
('psy-rnk-l1-27', 'RNK-L1-27', 'psychology', 'ranking-ordering', 1, 'ஒரு அணிவகுப்பு வரிசையில் காவலர் நந்தா இடமிருந்து 65-வது இடத்திலும், வலமிருந்து 44-வது இடத்திலும் உள்ளார் எனில், வரிசையில் உள்ள மொத்த நபர்கள் எத்தனை பேர்? (அடிப்படை வரிசை #27)', '["108","109","107","110"]'::jsonb, 0, 'மொத்த நபர்கள் = (இடது + வலது) − 1 = (65 + 44) − 1 = 108 பேர்.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', '90c0880d037232005260fba99e23e30c7e22bb8663f904364746ea5456407e41'),
('psy-rnk-l1-28', 'RNK-L1-28', 'psychology', 'ranking-ordering', 1, 'ஒரு அணிவகுப்பு வரிசையில் ஆய்வாளர் சங்கர் இடமிருந்து 67-வது இடத்திலும், வலமிருந்து 45-வது இடத்திலும் உள்ளார் எனில், வரிசையில் உள்ள மொத்த நபர்கள் எத்தனை பேர்? (அடிப்படை வரிசை #28)', '["111","112","110","113"]'::jsonb, 0, 'மொத்த நபர்கள் = (இடது + வலது) − 1 = (67 + 45) − 1 = 111 பேர்.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', 'cdf58737ed70487014ba6293773ffb1d5f19c2ffa33361bf9b4a21444b7845b5'),
('psy-rnk-l1-29', 'RNK-L1-29', 'psychology', 'ranking-ordering', 1, 'ஒரு அணிவகுப்பு வரிசையில் காவலர் பாரதி இடமிருந்து 69-வது இடத்திலும், வலமிருந்து 46-வது இடத்திலும் உள்ளார் எனில், வரிசையில் உள்ள மொத்த நபர்கள் எத்தனை பேர்? (அடிப்படை வரிசை #29)', '["114","115","113","116"]'::jsonb, 0, 'மொத்த நபர்கள் = (இடது + வலது) − 1 = (69 + 46) − 1 = 114 பேர்.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', 'd957db7ddaaac601216c1e4304fe87cb4dc2fb0fd521813996489c2f94fee695'),
('psy-rnk-l1-30', 'RNK-L1-30', 'psychology', 'ranking-ordering', 1, 'ஒரு அணிவகுப்பு வரிசையில் SI இளங்கோ இடமிருந்து 71-வது இடத்திலும், வலமிருந்து 47-வது இடத்திலும் உள்ளார் எனில், வரிசையில் உள்ள மொத்த நபர்கள் எத்தனை பேர்? (அடிப்படை வரிசை #30)', '["117","118","116","119"]'::jsonb, 0, 'மொத்த நபர்கள் = (இடது + வலது) − 1 = (71 + 47) − 1 = 117 பேர்.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', 'c159bbc2d19e86b04081019c6b7efcf93422263a4e3cc4d6e1eeca95df4fc607'),
('psy-rnk-l2-01', 'RNK-L2-01', 'psychology', 'ranking-ordering', 2, '33 பேர் கொண்ட SI பயிற்சி முகாமில், காவலர் முருகன் மேலிருந்து 14-வது இடத்தில் உள்ளார் எனில், கீழிருந்து அவரது தரம் என்ன? (தரவரிசை #1)', '["20","19","21","22"]'::jsonb, 0, 'கீழிருந்து தரம் = மொத்தம் − மேலிருந்து தரம் + 1 = 33 − 14 + 1 = 20.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', '11470884128bf5473823055a758981e2a1c56154f1fd188f83f76b0f7a4ffa43'),
('psy-rnk-l2-02', 'RNK-L2-02', 'psychology', 'ranking-ordering', 2, '36 பேர் கொண்ட SI பயிற்சி முகாமில், SI கார்த்திக் மேலிருந்து 16-வது இடத்தில் உள்ளார் எனில், கீழிருந்து அவரது தரம் என்ன? (தரவரிசை #2)', '["21","20","22","23"]'::jsonb, 0, 'கீழிருந்து தரம் = மொத்தம் − மேலிருந்து தரம் + 1 = 36 − 16 + 1 = 21.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', 'c7c71b4fd6fe9ef5f66e06494aa1b15fc471e471665f4456da1a18cca4b4c65a'),
('psy-rnk-l2-03', 'RNK-L2-03', 'psychology', 'ranking-ordering', 2, '39 பேர் கொண்ட SI பயிற்சி முகாமில், ஆய்வாளர் ரமேஷ் மேலிருந்து 18-வது இடத்தில் உள்ளார் எனில், கீழிருந்து அவரது தரம் என்ன? (தரவரிசை #3)', '["22","21","23","24"]'::jsonb, 0, 'கீழிருந்து தரம் = மொத்தம் − மேலிருந்து தரம் + 1 = 39 − 18 + 1 = 22.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', 'dfb3faa05c89dbaeb05ae959f5f22bb999ad3f0dee059f07426198b12f3d5daa'),
('psy-rnk-l2-04', 'RNK-L2-04', 'psychology', 'ranking-ordering', 2, '42 பேர் கொண்ட SI பயிற்சி முகாமில், காவலர் செந்தில் மேலிருந்து 20-வது இடத்தில் உள்ளார் எனில், கீழிருந்து அவரது தரம் என்ன? (தரவரிசை #4)', '["23","22","24","25"]'::jsonb, 0, 'கீழிருந்து தரம் = மொத்தம் − மேலிருந்து தரம் + 1 = 42 − 20 + 1 = 23.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', '66e7a6571cfb2a13022d16a13519f150c60d2beda667752b7385fb88b69adbb5'),
('psy-rnk-l2-05', 'RNK-L2-05', 'psychology', 'ranking-ordering', 2, '45 பேர் கொண்ட SI பயிற்சி முகாமில், SI அனிதா மேலிருந்து 22-வது இடத்தில் உள்ளார் எனில், கீழிருந்து அவரது தரம் என்ன? (தரவரிசை #5)', '["24","23","25","26"]'::jsonb, 0, 'கீழிருந்து தரம் = மொத்தம் − மேலிருந்து தரம் + 1 = 45 − 22 + 1 = 24.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', '1059ec4479c45018328fff2975e3a923bbe71b8db603fb29e66c852a6e2d9e75'),
('psy-rnk-l2-06', 'RNK-L2-06', 'psychology', 'ranking-ordering', 2, '48 பேர் கொண்ட SI பயிற்சி முகாமில், காவலர் விஜய் மேலிருந்து 24-வது இடத்தில் உள்ளார் எனில், கீழிருந்து அவரது தரம் என்ன? (தரவரிசை #6)', '["25","24","26","27"]'::jsonb, 0, 'கீழிருந்து தரம் = மொத்தம் − மேலிருந்து தரம் + 1 = 48 − 24 + 1 = 25.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', 'e055caec7de5d7736054ed02def48d9227f91830db813a797a6645d37add0b22'),
('psy-rnk-l2-07', 'RNK-L2-07', 'psychology', 'ranking-ordering', 2, '51 பேர் கொண்ட SI பயிற்சி முகாமில், ஹெட் கான்ஸ்டபிள் சிவா மேலிருந்து 26-வது இடத்தில் உள்ளார் எனில், கீழிருந்து அவரது தரம் என்ன? (தரவரிசை #7)', '["26","25","27","28"]'::jsonb, 0, 'கீழிருந்து தரம் = மொத்தம் − மேலிருந்து தரம் + 1 = 51 − 26 + 1 = 26.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', '8e24ceb9cb4c47dc88df4eae4ed69685883eaecdfc274e48e3920cb42139c597'),
('psy-rnk-l2-08', 'RNK-L2-08', 'psychology', 'ranking-ordering', 2, '54 பேர் கொண்ட SI பயிற்சி முகாமில், SI விக்ரம் மேலிருந்து 28-வது இடத்தில் உள்ளார் எனில், கீழிருந்து அவரது தரம் என்ன? (தரவரிசை #8)', '["27","26","28","29"]'::jsonb, 0, 'கீழிருந்து தரம் = மொத்தம் − மேலிருந்து தரம் + 1 = 54 − 28 + 1 = 27.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', '6f2d59c3c2064711f75fa66c1012225b5206ed74ddc300e5003a8bad752b5012'),
('psy-rnk-l2-09', 'RNK-L2-09', 'psychology', 'ranking-ordering', 2, '57 பேர் கொண்ட SI பயிற்சி முகாமில், காவலர் தினேஷ் மேலிருந்து 30-வது இடத்தில் உள்ளார் எனில், கீழிருந்து அவரது தரம் என்ன? (தரவரிசை #9)', '["28","27","29","30"]'::jsonb, 0, 'கீழிருந்து தரம் = மொத்தம் − மேலிருந்து தரம் + 1 = 57 − 30 + 1 = 28.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', '8f70986a1c824ecf11fdd4c712f7d1fde14327f9c1a68dd952c8d46cdd4e7773'),
