('psy-rnk-l2-27', 'RNK-L2-27', 'psychology', 'ranking-ordering', 2, '111 பேர் கொண்ட SI பயிற்சி முகாமில், காவலர் நந்தா மேலிருந்து 66-வது இடத்தில் உள்ளார் எனில், கீழிருந்து அவரது தரம் என்ன? (தரவரிசை #27)', '["46","45","47","48"]'::jsonb, 0, 'கீழிருந்து தரம் = மொத்தம் − மேலிருந்து தரம் + 1 = 111 − 66 + 1 = 46.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', 'a39f625070905fca876008e12a9e0a9d23543ffed1b47ba490777e14de6c77a2'),
('psy-rnk-l2-28', 'RNK-L2-28', 'psychology', 'ranking-ordering', 2, '114 பேர் கொண்ட SI பயிற்சி முகாமில், ஆய்வாளர் சங்கர் மேலிருந்து 68-வது இடத்தில் உள்ளார் எனில், கீழிருந்து அவரது தரம் என்ன? (தரவரிசை #28)', '["47","46","48","49"]'::jsonb, 0, 'கீழிருந்து தரம் = மொத்தம் − மேலிருந்து தரம் + 1 = 114 − 68 + 1 = 47.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', '3ec620493c49353d4b48dc2b0e16cc2ff2bf148061a9f7246036cdf2622f4c3e'),
('psy-rnk-l2-29', 'RNK-L2-29', 'psychology', 'ranking-ordering', 2, '117 பேர் கொண்ட SI பயிற்சி முகாமில், காவலர் பாரதி மேலிருந்து 70-வது இடத்தில் உள்ளார் எனில், கீழிருந்து அவரது தரம் என்ன? (தரவரிசை #29)', '["48","47","49","50"]'::jsonb, 0, 'கீழிருந்து தரம் = மொத்தம் − மேலிருந்து தரம் + 1 = 117 − 70 + 1 = 48.', 'மொத்தம் = இடது + வலது - 1.', 'ஒரு நபரே இருமுறை எண்ணப்படுவதால் 1-ஐ கழிக்க வேண்டும்.', 'easy', '7eb2d1969ca533668536c19e4f528946a870afff1289fb70ba6b22432b0f2a7f'),
