('psy-ana-l1-01', 'ANA-L1-01', 'psychology', 'analogy', 1, 'இந்தியா : புது தில்லி :: தமிழ்நாடு : ? (அடிப்படை ஒப்புமை #1)', '["சென்னை","மும்பை","டாலர்","சீறும்"]'::jsonb, 0, 'இந்தியா மற்றும் புது தில்லி இடையே உள்ள அதே உறவு தமிழ்நாடு மற்றும் ''சென்னை'' இடையே பொருந்துகிறது.', 'முதல் ஜோடியின் தர்க்க விதியை அடுத்த ஜோடிக்கு பொருத்துங்கள்.', 'எளிய கணித விதியை முன்னிலைப்படுத்தவும்.', 'easy', 'fb1fc3eac6b79712e828f6f3a41bcdd57426432146226c01975dde76f9e893cd'),
('psy-ana-l1-02', 'ANA-L1-02', 'psychology', 'analogy', 1, 'ஜப்பான் : யென் :: இந்தியா : ? (அடிப்படை ஒப்புமை #2)', '["ரூபாய்","மும்பை","டாலர்","சீறும்"]'::jsonb, 0, 'ஜப்பான் மற்றும் யென் இடையே உள்ள அதே உறவு இந்தியா மற்றும் ''ரூபாய்'' இடையே பொருந்துகிறது.', 'முதல் ஜோடியின் தர்க்க விதியை அடுத்த ஜோடிக்கு பொருத்துங்கள்.', 'எளிய கணித விதியை முன்னிலைப்படுத்தவும்.', 'easy', 'dd19b88c70c06d220a2f6c834380381562b9cc5747fa5ed44c8e703e68638e33'),
('psy-ana-l1-03', 'ANA-L1-03', 'psychology', 'analogy', 1, 'நாய் : குரைக்கும் :: சிங்கம் : ? (அடிப்படை ஒப்புமை #3)', '["கர்ஜிக்கும்","மும்பை","டாலர்","சீறும்"]'::jsonb, 0, 'நாய் மற்றும் குரைக்கும் இடையே உள்ள அதே உறவு சிங்கம் மற்றும் ''கர்ஜிக்கும்'' இடையே பொருந்துகிறது.', 'முதல் ஜோடியின் தர்க்க விதியை அடுத்த ஜோடிக்கு பொருத்துங்கள்.', 'எளிய கணித விதியை முன்னிலைப்படுத்தவும்.', 'easy', '85daaf8c1f476979cbe593ecce978dbf66aff7093b23c0a9f445abc1e8f015d4'),
('psy-ana-l1-04', 'ANA-L1-04', 'psychology', 'analogy', 1, 'காவலர் : துப்பாக்கி :: எழுத்தாளர் : ? (அடிப்படை ஒப்புமை #4)', '["பேனா","மும்பை","டாலர்","சீறும்"]'::jsonb, 0, 'காவலர் மற்றும் துப்பாக்கி இடையே உள்ள அதே உறவு எழுத்தாளர் மற்றும் ''பேனா'' இடையே பொருந்துகிறது.', 'முதல் ஜோடியின் தர்க்க விதியை அடுத்த ஜோடிக்கு பொருத்துங்கள்.', 'எளிய கணித விதியை முன்னிலைப்படுத்தவும்.', 'easy', '81a9c8a3b616db4f58252e837073afe1edf90564568cd35cc332283b84a8a8d7'),
('psy-ana-l1-05', 'ANA-L1-05', 'psychology', 'analogy', 1, 'இந்தியா : புது தில்லி :: தமிழ்நாடு : ? (அடிப்படை ஒப்புமை #5)', '["சென்னை","மும்பை","டாலர்","சீறும்"]'::jsonb, 0, 'இந்தியா மற்றும் புது தில்லி இடையே உள்ள அதே உறவு தமிழ்நாடு மற்றும் ''சென்னை'' இடையே பொருந்துகிறது.', 'முதல் ஜோடியின் தர்க்க விதியை அடுத்த ஜோடிக்கு பொருத்துங்கள்.', 'எளிய கணித விதியை முன்னிலைப்படுத்தவும்.', 'easy', '8cf9d84ce648aedf4a9cf8d7dabeac44cba5d9da8d597bdb8efd002cf7366b08'),
('psy-ana-l1-06', 'ANA-L1-06', 'psychology', 'analogy', 1, 'ஜப்பான் : யென் :: இந்தியா : ? (அடிப்படை ஒப்புமை #6)', '["ரூபாய்","மும்பை","டாலர்","சீறும்"]'::jsonb, 0, 'ஜப்பான் மற்றும் யென் இடையே உள்ள அதே உறவு இந்தியா மற்றும் ''ரூபாய்'' இடையே பொருந்துகிறது.', 'முதல் ஜோடியின் தர்க்க விதியை அடுத்த ஜோடிக்கு பொருத்துங்கள்.', 'எளிய கணித விதியை முன்னிலைப்படுத்தவும்.', 'easy', '0d3411e2f1ff2eb88c553cf26409dde8bd7937b254427f6bb39cb1856f578a51'),
